mapper.select:
select u.U_Name as pcnUserName, f.file_relation_id as fileRelationId,
from Pre_ProjectChangeName pcn left join SYS_User u on u.U_ID=pcn.PCN_User_ID left join Sys_File f on f.FileID=pcn.PCN_ID
and pcn.Te_Id = #{teId}
and pcn.P_Id=#{pId}
pcn.PCN_Old_Name like concat('%',#{pcnName},'%') or pcn.PCN_New_Name like concat('%',#{pcnName},'%')
order by p.${sortFiled} ${sortType}
order by pcn.PCN_Create_Time desc
limit #{start},#{size}

select count(1) from Pre_ProjectChangeName pcn left join SYS_User u on u.U_ID=pcn.PCN_User_ID
and pcn.Te_Id = #{teId}
and pcn.P_Id=#{pId}
pcn.PCN_Old_Name like concat('%',#{pcnName},'%') or pcn.PCN_New_Name like concat('%',#{pcnName},'%')
